"""Status helper tests never access a real server, Docker daemon or network."""

from contextlib import redirect_stdout
from io import StringIO
import json
from pathlib import Path
import subprocess
from types import SimpleNamespace
import unittest
from unittest.mock import Mock, patch

from cloud import server_status as status

TEST_QQ = "123456789"
TEST_ADMIN = "987654321"
# Independently generated by Node crypto.scryptSync with the upstream parameters.
WEBUI_AUTH = {
    "passwordSalt": "00112233445566778899aabbccddeeff",
    "passwordHash": "0c21099f4decaa24623bd9cef56776d7ef686dd55912820fd916029213ce819527"
                    "5dac5f1084a38dee8a18f89fab1304a933474d6b50b826087775668c39c375",
}


class RedactionTests(unittest.TestCase):
    def test_current_and_replaced_bootstrap_credentials_are_hidden(self):
        secrets = {"astrbot_password": "AaCurrent123", "snowluma_password": "BbCurrent456!",
                   "novnc_password": "VncA1234", "onebot_token": "current-token",
                   "deepseek_api_key": "sk-current-api-key"}
        logs = "\n".join([
            "known value=" + v for v in secrets.values()
        ] + ["Initial password: OLDabc123xyz", "initial credentials: user=admin password=OLDxyz123",
             "临时密码: OLD321", "remote desktop password: OLDsecret", "远程桌面密码: OLD987",
             '{"api_key":"sk-unknown123456","accessToken":"oldAccessToken"}',
             "Authorization: Bearer xyz.123", "token=otherToken", "passwd='with spaces'",
             "-----BEGIN OPENSSH PRIVATE KEY-----\nprivate material\n-----END OPENSSH PRIVATE KEY-----"])
        safe = status.make_redactor(secrets)(logs)
        for secret in [*secrets.values(), "OLDabc123xyz", "OLDxyz123", "OLD321", "OLDsecret",
                       "OLD987", "sk-unknown123456", "oldAccessToken", "xyz.123", "otherToken",
                       "with spaces", "private material"]:
            self.assertNotIn(secret, safe)
        self.assertIn("known value=", safe)

    def test_ansi_and_controls_are_removed(self):
        self.assertEqual("hello", status.make_redactor({})("\x1b[31mhello\x1b[0m\x00"))


class DockerTests(unittest.TestCase):
    def test_fixed_arguments_without_shell_and_timeout(self):
        with patch.object(status.subprocess, "run", return_value=Mock()) as run:
            status.run_docker(["inspect", "jingjing-astrbot"])
        self.assertEqual(["docker", "inspect", "jingjing-astrbot"], run.call_args.args[0])
        self.assertNotIn("shell", run.call_args.kwargs)
        self.assertEqual(3, run.call_args.kwargs["timeout"])
        self.assertIs(status.subprocess.DEVNULL, run.call_args.kwargs["stdin"])

    def test_missing_docker_and_timeout_are_safe(self):
        for error in (FileNotFoundError("secret"), subprocess.TimeoutExpired("docker", 3)):
            with patch.object(status.subprocess, "run", side_effect=error):
                self.assertIsNone(status.run_docker(["inspect"]))

    def test_inspect_only_accepts_owned_exact_named_containers(self):
        def item(name, project="jingjing"):
            return {"Name": name, "Config": {"Image": "image:v1", "Env": ["KEY=never-output"],
                    "Labels": {"com.docker.compose.project": project}},
                    "State": {"Status": "running", "StartedAt": "date", "Health": {"Status": "healthy"}}}
        raw = [item("/jingjing-astrbot"), item("/jingjing-snowluma", "other"), item("/unrelated")]
        with patch.object(status, "run_docker", return_value=SimpleNamespace(returncode=0, stdout=json.dumps(raw))):
            services, owned = status.inspect_services(str)
        self.assertEqual({"astrbot"}, owned)
        self.assertEqual("running", services["astrbot"]["state"])
        self.assertEqual("unavailable", services["snowluma"]["state"])
        self.assertNotIn("never-output", json.dumps(services))

    def test_partial_inspect_json_is_kept_when_other_container_is_absent(self):
        raw = [{"Name": "/jingjing-astrbot", "Config": {"Labels": {"com.docker.compose.project": "jingjing"}},
                "State": {"Status": "running"}}]
        with patch.object(status, "run_docker", return_value=SimpleNamespace(returncode=1, stdout=json.dumps(raw))):
            services, owned = status.inspect_services(str)
        self.assertEqual({"astrbot"}, owned)
        self.assertEqual("not_found", services["snowluma"]["state"])

    def test_logs_include_application_stderr_and_redact_before_splitting(self):
        result = SimpleNamespace(returncode=0, stdout="ready\n", stderr="Initial password: OLD123\nwarn")
        with patch.object(status, "run_docker", return_value=result) as run:
            lines = status.service_logs("astrbot", status.make_redactor({}))
        self.assertIn("ready", lines)
        self.assertIn("warn", lines)
        self.assertNotIn("OLD123", repr(lines))
        self.assertEqual(["logs", "--timestamps", "--tail", "80", "jingjing-astrbot"], run.call_args.args[0])


class SnowlumaTests(unittest.TestCase):
    def call(self, accounts, connections):
        with patch.object(status, "read_json", return_value=WEBUI_AUTH), \
             patch.object(status, "build_opener") as build, patch.object(status, "request_json") as request:
            request.side_effect = [{"success": True, "token": "private-session"}, accounts, connections, {"success": True}]
            result = status.snowluma_status({"snowluma_password": "private-password"}, TEST_QQ)
        self.assertEqual("/api/login", request.call_args_list[0].args[1])
        self.assertEqual({"password": "private-password"}, request.call_args_list[0].kwargs["body"])
        self.assertEqual("/api/logout", request.call_args_list[-1].args[1])
        return result

    def test_target_account_and_only_astrbot_wsclient_report_connected(self):
        self.assertEqual((True, True), self.call(
            {"list": [{"uin": TEST_QQ}]},
            {"list": [{"uin": TEST_QQ, "adapters": [{"name": "astrbot", "kind": "wsClient", "status": "ok"}]}]},
        ))

    def test_other_account_or_other_adapter_is_not_success(self):
        self.assertEqual((False, False), self.call(
            {"list": [{"uin": "11111"}]},
            {"list": [{"uin": "11111", "adapters": [{"name": "astrbot", "kind": "wsClient", "status": "ok"}]}]},
        ))
        self.assertEqual((True, False), self.call(
            {"list": [{"uin": TEST_QQ}]},
            {"list": [{"uin": TEST_QQ, "adapters": [{"name": "other", "kind": "wsClient", "status": "ok"}]}]},
        ))

    def test_unavailable_api_is_unknown_not_offline(self):
        self.assertEqual((None, None), self.call(None, None))
        with patch.object(status, "snowluma_password_matches", return_value=True), \
             patch.object(status, "request_json", return_value={"success": False, "message": "private error"}):
            self.assertEqual((None, None), status.snowluma_status({"snowluma_password": "password"}, TEST_QQ))
        self.assertEqual((None, None), status.snowluma_status({}, TEST_QQ))
        self.assertEqual((None, None), status.snowluma_status({"snowluma_password": "password"}, ""))

    def test_changed_password_does_not_attempt_http_authentication(self):
        with patch.object(status, "read_json", return_value=WEBUI_AUTH), \
             patch.object(status, "build_opener") as build, patch.object(status, "request_json") as request:
            self.assertEqual((None, None), status.snowluma_status({"snowluma_password": "old-password"}, TEST_QQ))
        build.assert_not_called()
        request.assert_not_called()

    def test_missing_auth_file_does_not_attempt_http_authentication(self):
        with patch.object(status, "read_json", return_value={}) as read, \
             patch.object(status, "request_json") as request:
            self.assertEqual((None, None), status.snowluma_status({"snowluma_password": "private-password"}, TEST_QQ))
        self.assertEqual(status.ROOT / "snowluma/data/config/webui.json", read.call_args.args[0])
        request.assert_not_called()

    def test_hash_parameters_match_upstream_node_fixture_and_invalid_formats_fail_closed(self):
        with patch.object(status, "read_json", return_value=WEBUI_AUTH):
            self.assertTrue(status.snowluma_password_matches("private-password"))
            self.assertFalse(status.snowluma_password_matches("wrong-password"))
        for malformed in ({"passwordSalt": "z" * 32, "passwordHash": "0" * 128},
                          {"passwordSalt": "0" * 32, "passwordHash": "0" * 64},
                          {"passwordSalt": [], "passwordHash": None}):
            with self.subTest(state=malformed), patch.object(status, "read_json", return_value=malformed):
                self.assertFalse(status.snowluma_password_matches("private-password"))

    def test_json_request_is_local_bounded_and_does_not_print_exceptions(self):
        opener = Mock()
        opener.open.side_effect = OSError("password=secret")
        with patch.object(status.time, "monotonic", return_value=10):
            self.assertIsNone(status.request_json(opener, "/api/login", 12, body={"password": "private"}))
        request = opener.open.call_args.args[0]
        self.assertEqual("http://127.0.0.1:5099/api/login", request.full_url)
        self.assertEqual(2, opener.open.call_args.kwargs["timeout"])
        self.assertEqual("application/json", request.get_header("Content-type"))

    def test_expired_budget_does_not_open_network(self):
        opener = Mock()
        with patch.object(status.time, "monotonic", return_value=10):
            self.assertIsNone(status.request_json(opener, "/api/login", 9))
        opener.open.assert_not_called()

    def test_redirects_never_forward_credentials(self):
        self.assertIsNone(status.NoRedirect().redirect_request(None, None, 302, "", {}, "https://evil.example"))


class SnapshotTests(unittest.TestCase):
    def test_identifiers_are_loaded_from_private_metadata_and_validated(self):
        with patch.object(status, "read_json", return_value={"bot_qq": TEST_QQ, "admin_qq": TEST_ADMIN}) as read:
            self.assertEqual({"bot_qq": TEST_QQ, "admin_qq": TEST_ADMIN}, status.bot_settings())
        self.assertEqual(status.ROOT / "bot.json", read.call_args.args[0])
        with patch.object(status, "read_json", return_value={"bot_qq": "invalid", "admin_qq": []}):
            self.assertEqual({"bot_qq": "", "admin_qq": ""}, status.bot_settings())

    def test_linux_proc_values_and_disk_sizes_are_bytes(self):
        files = {"/etc/os-release": 'PRETTY_NAME="Ubuntu 22.04.5 LTS"',
                 "/proc/uptime": "123.89 42.0", "/proc/meminfo": "MemTotal: 4000 kB\nMemAvailable: 2000 kB\n"}
        with patch.object(Path, "read_text", autospec=True, side_effect=lambda p, **kw: files[str(p).replace('\\', '/')]), \
             patch.object(status.socket, "gethostname", return_value="server"), \
             patch.object(status.os, "cpu_count", return_value=2), \
             patch.object(status.os, "getloadavg", create=True, return_value=(1, 2, 3)), \
             patch.object(status.shutil, "disk_usage", return_value=SimpleNamespace(total=9000, used=4000, free=5000)):
            result = status.server_info()
        self.assertEqual("Ubuntu 22.04.5 LTS", result["os"])
        self.assertEqual(123, result["uptime_seconds"])
        self.assertEqual({"total": 4096000, "available": 2048000}, result["memory"])
        self.assertEqual({"total": 9000, "used": 4000, "free": 5000}, result["disk"])

    def test_model_uses_selected_enabled_provider(self):
        config = {"agent_runner": {"config": {"model": {"provider_id": "target"}}},
                  "provider": [{"id": "first", "model": "wrong"}, {"id": "target", "model": "deepseek-flash"}]}
        self.assertEqual("deepseek-flash", status.model_name(config))
        self.assertEqual("", status.model_name({"provider": None}))

    def test_snapshot_schema_and_no_logs_for_unowned_containers(self):
        with patch.object(status, "read_json", return_value={}), \
             patch.object(status, "bot_settings", return_value={"bot_qq": TEST_QQ, "admin_qq": TEST_ADMIN}), \
             patch.object(status, "server_info", return_value={"hostname": "host"}), \
             patch.object(status, "snowluma_status", return_value=(False, False)), \
             patch.object(status, "inspect_services", return_value=({}, set())), \
             patch.object(status, "service_logs") as logs:
            result = status.collect_status()
        self.assertEqual(TEST_QQ, result["bot"]["qq"])
        self.assertEqual(TEST_ADMIN, result["bot"]["admin_qq"])
        self.assertIs(result["bot"]["online"], False)
        self.assertEqual({"astrbot": [], "snowluma": []}, result["logs"])
        logs.assert_not_called()

    def test_main_failure_is_json_only_and_hides_error_message(self):
        output = StringIO()
        with patch.object(status, "collect_status", side_effect=RuntimeError("private-api-key")), \
             patch.object(status, "bot_settings", return_value={"bot_qq": "", "admin_qq": ""}), redirect_stdout(output):
            status.main()
        value = json.loads(output.getvalue())
        self.assertNotIn("private-api-key", output.getvalue())
        self.assertIsNone(value["bot"]["online"])


if __name__ == "__main__":
    unittest.main()
